 SkinDataProvider provider;provider.beginFrame(kind);for(auto& d:SkinBindingRegistry::definitions())if(SkinBindingRegistry::allowed(d.id,kind)){
 if(d.id==BindingId::PlayJudgementGrade)provider.set(d.id,std::int64_t(0));else if(d.id==BindingId::PlayJudgementAge)provider.set(d.id,0.0);else if(d.type==BindingType::String)provider.set(d.id,std::string(d.id==BindingId::SongTitle?"Test Song":d.id==BindingId::SongArtist?"Test Artist":d.id==BindingId::ResultRank?"AA":d.id==BindingId::SelectSpeedText?"1.00x":(d.id==BindingId::PlayJudgementProfile||d.id==BindingId::PlayGaugeMode||d.id==BindingId::SelectGaugeMode||d.id==BindingId::SelectJudgementText)?"NORMAL":"CLEAR"));
 else if(d.type==BindingType::Integer)provider.set(d.id,std::int64_t(d.id==BindingId::PlayCombo?256:882460));else if(d.type==BindingType::Real)provider.set(d.id,d.id==BindingId::ChartLevel?12.0:150.0);else provider.set(d.id,true);}
 provider.endFrame();editorPreviewData=provider;editorPreviewAt=std::chrono::steady_clock::now();renderer.emit("judgement");editorPreviewSeconds=0;for(const auto& element:loaded.package->screens.at(kind).elements)if(element.hud.images())editorPreviewSeconds=std::max(editorPreviewSeconds,element.hud.displayMs/1000);KillTimer(mainWindow,777);if(editorPreviewSeconds>0||renderer.animating())SetTimer(mainWindow,777,16,nullptr);if(auto e=renderer.update(&provider.snapshot()))throw std::runtime_error(e->message);InvalidateRect(canvas,nullptr,FALSE);
